//! The public code format (DECISIONS D24): CPython 3.15 wordcode.
//!
//! A code object's `co_code` is a sequence of 2-byte code units `(opcode, oparg)`; opargs wider
//! than 8 bits use `EXTENDED_ARG` prefixes, and some opcodes are followed by a fixed number of
//! inline `CACHE` units (zero in freshly compiled code).  Offsets, jump distances and
//! exception-table values are counted in code units.  Opcode numbers come from the public
//! header `spec/Include/opcode_ids.h` (see `opcodes.rs`, generated by `tools/gen_opcodes`).
//!
//! This module holds the opcode metadata (argument kinds, cache sizes, stack effects), the
//! public [`CodeObject`] the compiler produces, and encoders/decoders for `co_linetable` and
//! `co_exceptiontable` shared by the compiler, the runtime and the `dis` support code.

pub mod dis;
pub mod opcodes;
pub use opcodes as op;

use op::*;

// ---------------------------------------------------------------------------- metadata

/// Name of an opcode (real or pseudo), if it exists.
pub fn opname(code: u16) -> Option<&'static str> {
    // ALL is small; a linear scan is fine for metadata queries, but keep a cached table
    // for the hot path used by decoders.
    static TABLE: std::sync::OnceLock<Vec<Option<&'static str>>> = std::sync::OnceLock::new();
    let t = TABLE.get_or_init(|| {
        let mut v = vec![None; 512];
        for &(n, c) in ALL.iter() {
            v[c as usize] = Some(n);
        }
        v
    });
    t.get(code as usize).copied().flatten()
}

/// Opcode number for a name.
pub fn opcode_by_name(name: &str) -> Option<u16> {
    ALL.iter().find(|(n, _)| *n == name).map(|&(_, c)| c)
}

pub fn is_pseudo(code: u16) -> bool {
    code >= 256
}

pub fn is_valid(code: i64) -> bool {
    (0..512).contains(&code) && opname(code as u16).is_some()
}

/// Specialised and instrumented opcodes map back to the generic opcode they replace.
pub fn deopt(code: u16) -> u16 {
    if code == BINARY_OP_INPLACE_ADD_UNICODE {
        return BINARY_OP;
    }
    if (MIN_SPECIALIZED_OPCODE..MIN_INSTRUMENTED_OPCODE).contains(&code) {
        return specialization_base(code).unwrap_or(code);
    }
    match code {
        INSTRUMENTED_END_FOR => END_FOR,
        INSTRUMENTED_POP_ITER => POP_ITER,
        INSTRUMENTED_END_SEND => END_SEND,
        INSTRUMENTED_FOR_ITER => FOR_ITER,
        INSTRUMENTED_JUMP_FORWARD => JUMP_FORWARD,
        INSTRUMENTED_NOT_TAKEN => NOT_TAKEN,
        INSTRUMENTED_POP_JUMP_IF_TRUE => POP_JUMP_IF_TRUE,
        INSTRUMENTED_POP_JUMP_IF_FALSE => POP_JUMP_IF_FALSE,
        INSTRUMENTED_POP_JUMP_IF_NONE => POP_JUMP_IF_NONE,
        INSTRUMENTED_POP_JUMP_IF_NOT_NONE => POP_JUMP_IF_NOT_NONE,
        INSTRUMENTED_RESUME => RESUME,
        INSTRUMENTED_RETURN_VALUE => RETURN_VALUE,
        INSTRUMENTED_YIELD_VALUE => YIELD_VALUE,
        INSTRUMENTED_END_ASYNC_FOR => END_ASYNC_FOR,
        INSTRUMENTED_LOAD_SUPER_ATTR => LOAD_SUPER_ATTR,
        INSTRUMENTED_CALL => CALL,
        INSTRUMENTED_CALL_KW => CALL_KW,
        INSTRUMENTED_CALL_FUNCTION_EX => CALL_FUNCTION_EX,
        INSTRUMENTED_JUMP_BACKWARD => JUMP_BACKWARD,
        _ => code,
    }
}

/// For a specialised opcode, the generic opcode it specialises (by naming convention of the
/// specialised family, with the irregular cases listed explicitly).
pub fn specialization_base(code: u16) -> Option<u16> {
    if code == BINARY_OP_INPLACE_ADD_UNICODE {
        return Some(BINARY_OP);
    }
    if !(MIN_SPECIALIZED_OPCODE..MIN_INSTRUMENTED_OPCODE).contains(&code) {
        return None;
    }
    let name = opname(code)?;
    let base = match name {
        "RESUME_CHECK" | "RESUME_CHECK_JIT" => "RESUME",
        "JUMP_BACKWARD_JIT" | "JUMP_BACKWARD_NO_JIT" => "JUMP_BACKWARD",
        "CALL_ALLOC_AND_ENTER_INIT" => "CALL",
        n if n.starts_with("CALL_KW_") => "CALL_KW",
        n if n.starts_with("CALL_EX_") => "CALL_FUNCTION_EX",
        n => {
            // longest generic name that prefixes the specialised one
            const FAMILIES: [&str; 17] = [
                "BINARY_OP",
                "CALL",
                "COMPARE_OP",
                "CONTAINS_OP",
                "FOR_ITER",
                "GET_ITER",
                "LOAD_ATTR",
                "LOAD_GLOBAL",
                "LOAD_SUPER_ATTR",
                "SEND",
                "STORE_ATTR",
                "STORE_SUBSCR",
                "TO_BOOL",
                "UNPACK_SEQUENCE",
                "LOAD_CONST",
                "STORE_FAST",
                "LOAD_FAST",
            ];
            let mut best: Option<&str> = None;
            for f in FAMILIES {
                if n.len() > f.len() && n.starts_with(f) && n.as_bytes()[f.len()] == b'_' && best.is_none_or(|b| f.len() > b.len()) {
                    best = Some(f);
                }
            }
            best?
        }
    };
    opcode_by_name(base)
}

/// Generic opcodes that have specialised forms, with their specialisations (header order).
pub fn specializations() -> Vec<(u16, Vec<u16>)> {
    let mut out: Vec<(u16, Vec<u16>)> = Vec::new();
    let mut add = |base: u16, s: u16| {
        if let Some(e) = out.iter_mut().find(|(b, _)| *b == base) {
            e.1.push(s);
        } else {
            out.push((base, vec![s]));
        }
    };
    add(BINARY_OP, BINARY_OP_INPLACE_ADD_UNICODE);
    for &(_, c) in ALL.iter() {
        if (MIN_SPECIALIZED_OPCODE..MIN_INSTRUMENTED_OPCODE).contains(&c) {
            if let Some(b) = specialization_base(c) {
                add(b, c);
            }
        }
    }
    out
}

/// Real opcodes that take an argument (`op >= HAVE_ARGUMENT`), plus pseudo-instructions
/// with an argument.
pub fn has_arg(code: u16) -> bool {
    if code < 256 {
        let d = deopt(code);
        if d != code {
            return has_arg(d);
        }
        if code >= MIN_INSTRUMENTED_OPCODE {
            return code == ENTER_EXECUTOR;
        }
        // HAVE_ARGUMENT itself (WITH_EXCEPT_START) takes no argument
        return code > HAVE_ARGUMENT && opname(code).is_some();
    }
    matches!(
        code,
        JUMP | JUMP_IF_FALSE | JUMP_IF_TRUE | JUMP_NO_INTERRUPT | LOAD_CLOSURE | SETUP_CLEANUP | SETUP_FINALLY | SETUP_WITH | STORE_FAST_MAYBE_NULL
    )
}

pub fn has_const(code: u16) -> bool {
    deopt(code) == LOAD_CONST
}

pub fn has_name(code: u16) -> bool {
    matches!(
        deopt(code),
        LOAD_NAME
            | STORE_NAME
            | DELETE_NAME
            | LOAD_GLOBAL
            | STORE_GLOBAL
            | DELETE_GLOBAL
            | LOAD_ATTR
            | STORE_ATTR
            | DELETE_ATTR
            | IMPORT_NAME
            | IMPORT_FROM
            | LOAD_FROM_DICT_OR_GLOBALS
            | LOAD_SUPER_ATTR
    )
}

/// Instructions with a jump target (real: relative; pseudo: label).
pub fn has_jump(code: u16) -> bool {
    matches!(
        deopt(code),
        FOR_ITER
            | JUMP_FORWARD
            | JUMP_BACKWARD
            | JUMP_BACKWARD_NO_INTERRUPT
            | POP_JUMP_IF_FALSE
            | POP_JUMP_IF_TRUE
            | POP_JUMP_IF_NONE
            | POP_JUMP_IF_NOT_NONE
            | SEND
            | END_ASYNC_FOR
            | JUMP
            | JUMP_IF_FALSE
            | JUMP_IF_TRUE
            | JUMP_NO_INTERRUPT
    )
}

pub fn has_free(code: u16) -> bool {
    matches!(deopt(code), LOAD_DEREF | STORE_DEREF | DELETE_DEREF | MAKE_CELL | LOAD_FROM_DICT_OR_DEREF)
}

pub fn has_local(code: u16) -> bool {
    matches!(
        deopt(code),
        LOAD_FAST
            | LOAD_FAST_CHECK
            | LOAD_FAST_AND_CLEAR
            | LOAD_FAST_BORROW
            | LOAD_FAST_LOAD_FAST
            | LOAD_FAST_BORROW_LOAD_FAST_BORROW
            | STORE_FAST
            | STORE_FAST_LOAD_FAST
            | STORE_FAST_STORE_FAST
            | DELETE_FAST
            | LOAD_CLOSURE
            | STORE_FAST_MAYBE_NULL
    )
}

/// Pseudo-instructions that set up an exception handler.
pub fn has_exc(code: u16) -> bool {
    matches!(code, SETUP_FINALLY | SETUP_CLEANUP | SETUP_WITH)
}

/// Backward jumps (relative to the end of the instruction, going back).
pub fn is_backward_jump(code: u16) -> bool {
    matches!(deopt(code), JUMP_BACKWARD | JUMP_BACKWARD_NO_INTERRUPT | END_ASYNC_FOR)
}

/// Instructions that never fall through.
pub fn is_terminator(code: u16) -> bool {
    matches!(
        code,
        RETURN_VALUE | RAISE_VARARGS | RERAISE | JUMP_FORWARD | JUMP_BACKWARD | JUMP_BACKWARD_NO_INTERRUPT | JUMP | JUMP_NO_INTERRUPT
    )
}

/// Inline cache layout per generic opcode: (field name, size in code units).
pub fn cache_format(code: u16) -> &'static [(&'static str, u32)] {
    match deopt(code) {
        LOAD_GLOBAL => &[("counter", 1), ("index", 1), ("module_keys_version", 1), ("builtin_keys_version", 1)],
        BINARY_OP => &[("counter", 1), ("descr", 4)],
        UNPACK_SEQUENCE => &[("counter", 1)],
        COMPARE_OP => &[("counter", 1)],
        CONTAINS_OP => &[("counter", 1)],
        FOR_ITER => &[("counter", 1)],
        GET_ITER => &[("counter", 1)],
        LOAD_SUPER_ATTR => &[("counter", 1)],
        LOAD_ATTR => &[("counter", 1), ("version", 2), ("keys_version", 2), ("descr", 4)],
        STORE_ATTR => &[("counter", 1), ("version", 2), ("index", 1)],
        CALL => &[("counter", 1), ("func_version", 2)],
        CALL_KW => &[("counter", 1), ("func_version", 2)],
        CALL_FUNCTION_EX => &[("counter", 1)],
        STORE_SUBSCR => &[("counter", 1)],
        SEND => &[("counter", 1)],
        JUMP_BACKWARD => &[("counter", 1)],
        TO_BOOL => &[("counter", 1), ("version", 2)],
        POP_JUMP_IF_TRUE | POP_JUMP_IF_FALSE | POP_JUMP_IF_NONE | POP_JUMP_IF_NOT_NONE => &[("counter", 1)],
        RESUME => &[("counter", 1)],
        _ => &[],
    }
}

/// Number of inline CACHE code units following `code`.
pub fn cache_entries(code: u16) -> u32 {
    if code >= 256 {
        return 0;
    }
    cache_format(code).iter().map(|(_, n)| n).sum()
}

/// Stack effect of an instruction. `jump`: Some(true) = effect when the branch / handler is
/// taken, Some(false) = fall-through, None = maximum of both. Returns None for unknown opcodes.
pub fn stack_effect(code: u16, oparg: i32, jump: Option<bool>) -> Option<i32> {
    let n = oparg;
    let pick = |j: i32, nj: i32| -> i32 {
        match jump {
            Some(true) => j,
            Some(false) => nj,
            None => j.max(nj),
        }
    };
    let code = if code < 256 && code != deopt(code) { deopt(code) } else { code };
    let e = match code {
        CACHE | RESERVED | NOP | NOT_TAKEN | EXTENDED_ARG | RESUME => 0,
        BINARY_SLICE => -2,
        BUILD_TEMPLATE => -1,
        CALL_FUNCTION_EX => -3,
        CHECK_EG_MATCH | CHECK_EXC_MATCH => 0,
        CLEANUP_THROW => -1,
        DELETE_SUBSCR => -2,
        END_FOR => -1,
        END_SEND => -2,
        EXIT_INIT_CHECK => -1,
        FORMAT_SIMPLE => 0,
        FORMAT_WITH_SPEC => -1,
        GET_AITER => 0,
        GET_ANEXT => 1,
        GET_LEN => 1,
        INTERPRETER_EXIT => -1,
        LOAD_BUILD_CLASS | LOAD_LOCALS => 1,
        MAKE_FUNCTION => 0,
        MATCH_KEYS | MATCH_MAPPING | MATCH_SEQUENCE => 1,
        POP_EXCEPT => -1,
        POP_ITER => -2,
        POP_TOP => -1,
        PUSH_EXC_INFO | PUSH_NULL | RETURN_GENERATOR => 1,
        RETURN_VALUE => -1,
        SETUP_ANNOTATIONS => 0,
        STORE_SLICE => -4,
        STORE_SUBSCR => -3,
        TO_BOOL | UNARY_INVERT | UNARY_NEGATIVE | UNARY_NOT => 0,
        WITH_EXCEPT_START => 1,
        BINARY_OP => -1,
        BUILD_INTERPOLATION => -1 - (n & 1),
        BUILD_LIST | BUILD_SET | BUILD_TUPLE | BUILD_STRING | BUILD_SLICE => 1 - n,
        BUILD_MAP => 1 - 2 * n,
        CALL => -1 - n,
        CALL_KW => -2 - n,
        CALL_INTRINSIC_1 => 0,
        CALL_INTRINSIC_2 => -1,
        COMPARE_OP | CONTAINS_OP | IS_OP => -1,
        CONVERT_VALUE => 0,
        COPY => 1,
        COPY_FREE_VARS | MAKE_CELL => 0,
        DELETE_ATTR => -1,
        DELETE_DEREF | DELETE_FAST | DELETE_GLOBAL | DELETE_NAME => 0,
        DICT_MERGE | DICT_UPDATE | LIST_APPEND | LIST_EXTEND | SET_ADD | SET_UPDATE => -1,
        END_ASYNC_FOR => -2,
        FOR_ITER => 1,
        GET_AWAITABLE => 0,
        GET_ITER => 1,
        IMPORT_FROM => 1,
        IMPORT_NAME => -1,
        JUMP_BACKWARD | JUMP_BACKWARD_NO_INTERRUPT | JUMP_FORWARD => 0,
        LOAD_ATTR => n & 1,
        LOAD_COMMON_CONSTANT | LOAD_CONST | LOAD_DEREF | LOAD_FAST | LOAD_FAST_AND_CLEAR | LOAD_FAST_BORROW
        | LOAD_FAST_CHECK | LOAD_NAME | LOAD_SMALL_INT => 1,
        LOAD_FAST_LOAD_FAST | LOAD_FAST_BORROW_LOAD_FAST_BORROW => 2,
        LOAD_FROM_DICT_OR_DEREF | LOAD_FROM_DICT_OR_GLOBALS => 0,
        LOAD_GLOBAL => 1 + (n & 1),
        LOAD_SPECIAL => 1,
        LOAD_SUPER_ATTR => -2 + (n & 1),
        MAP_ADD => -2,
        MATCH_CLASS => -2,
        POP_JUMP_IF_FALSE | POP_JUMP_IF_TRUE | POP_JUMP_IF_NONE | POP_JUMP_IF_NOT_NONE => -1,
        RAISE_VARARGS => -n,
        RERAISE => -1,
        SEND => 0,
        SET_FUNCTION_ATTRIBUTE => -1,
        STORE_ATTR => -2,
        STORE_DEREF | STORE_FAST | STORE_GLOBAL | STORE_NAME => -1,
        STORE_FAST_LOAD_FAST => 0,
        STORE_FAST_STORE_FAST => -2,
        SWAP => 0,
        UNPACK_EX => (n & 0xff) + (n >> 8),
        UNPACK_SEQUENCE => n - 1,
        YIELD_VALUE => 0,
        // pseudo-instructions
        ANNOTATIONS_PLACEHOLDER | JUMP | JUMP_NO_INTERRUPT | POP_BLOCK => 0,
        JUMP_IF_FALSE | JUMP_IF_TRUE => 0,
        LOAD_CLOSURE => 1,
        STORE_FAST_MAYBE_NULL => -1,
        SETUP_FINALLY => pick(1, 0),
        SETUP_CLEANUP => pick(2, 0),
        SETUP_WITH => pick(1, 0),
        _ => return None,
    };
    Some(e)
}

