/// `COMPARE_OP` comparison names (oparg >> 5).
pub const CMP_OP: [&str; 6] = ["<", "<=", "==", "!=", ">", ">="];
/// Low bits of the `COMPARE_OP` oparg that the specialiser uses (which outcomes are "true").
pub const CMP_MASK: [u32; 6] = [2, 2 | 8, 8, 1 | 2 | 4, 4, 4 | 8];
/// `COMPARE_OP` oparg bit asking for a bool result.
pub const CMP_TO_BOOL: u32 = 16;

pub fn compare_oparg(cmp: u32, to_bool: bool) -> u32 {
    (cmp << 5) | CMP_MASK[cmp as usize] | if to_bool { CMP_TO_BOOL } else { 0 }
}

