// ---------------------------------------------------------------------------- code object

#[derive(Clone, Debug, PartialEq)]
pub enum Constant {
    None,
    Bool(bool),
    Ellipsis,
    Int(i64),
    /// big int as decimal digits with sign
    BigInt { neg: bool, decimal: String },
    Float(f64),
    Complex { real: f64, imag: f64 },
    /// code points (may contain lone surrogates)
    Str(Vec<u32>),
    Bytes(Vec<u8>),
    Tuple(Vec<Constant>),
    FrozenSet(Vec<Constant>),
    /// `slice(start, stop, step)` of constants
    Slice(Box<[Constant; 3]>),
    Code(Box<CodeObject>),
}

/// The public fields of a code object, as CPython 3.15 defines them.
#[derive(Clone, Debug, PartialEq, Default)]
pub struct CodeObject {
    pub name: String,
    pub qualname: String,
    pub filename: String,
    pub firstlineno: u32,
    pub argcount: u32,
    pub posonlyargcount: u32,
    pub kwonlyargcount: u32,
    pub flags: u32,
    pub stacksize: u32,
    /// `co_code`: wordcode with zeroed inline caches
    pub code: Vec<u8>,
    pub consts: Vec<Constant>,
    pub names: Vec<String>,
    pub localsplusnames: Vec<String>,
    /// CO_FAST_* kind bits per localsplus entry
    pub localspluskinds: Vec<u8>,
    /// `co_linetable`
    pub linetable: Vec<u8>,
    /// `co_exceptiontable`
    pub exceptiontable: Vec<u8>,
}

// ---------------------------------------------------------------------------- instruction decoding

/// One decoded instruction of a wordcode string.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Instr {
    /// code-unit offset of the opcode (after any EXTENDED_ARG prefixes)
    pub offset: u32,
    /// code-unit offset of the first EXTENDED_ARG prefix (== offset if none)
    pub start: u32,
    pub op: u8,
    /// argument including EXTENDED_ARG contributions
    pub arg: u32,
    /// inline cache units after the instruction
    pub ncache: u32,
}

impl Instr {
    /// Offset (code units) just after the instruction's caches.
    pub fn next(&self) -> u32 {
        self.offset + 1 + self.ncache
    }
    /// Jump target in code units, for jump instructions.
    pub fn jump_target(&self) -> Option<u32> {
        jump_target(self.op as u16, self.next(), self.arg)
    }
}

/// Target (code units) of a real jump instruction whose caches end at `next`.
pub fn jump_target(code: u16, next: u32, arg: u32) -> Option<u32> {
    let d = deopt(code);
    if !has_jump(d) || d >= 256 {
        return None;
    }
    if is_backward_jump(d) {
        Some(next.wrapping_sub(arg))
    } else {
        Some(next.wrapping_add(arg))
    }
}

/// Decode `co_code` into instructions (EXTENDED_ARG prefixes folded into the following
/// instruction; caches skipped). A trailing odd byte is ignored.
pub fn instructions(code: &[u8]) -> Vec<Instr> {
    let n = code.len() / 2;
    let mut out = Vec::new();
    let mut i = 0usize;
    let mut ext: u32 = 0;
    let mut start: Option<u32> = None;
    while i < n {
        let op = code[2 * i];
        let arg = code[2 * i + 1] as u32 | ext;
        if op as u16 == EXTENDED_ARG {
            ext = arg << 8;
            if start.is_none() {
                start = Some(i as u32);
            }
            i += 1;
            continue;
        }
        let ncache = cache_entries(deopt(op as u16));
        out.push(Instr { offset: i as u32, start: start.unwrap_or(i as u32), op, arg, ncache });
        ext = 0;
        start = None;
        i += 1 + ncache as usize;
    }
    out
}

// ---------------------------------------------------------------------------- exception table

/// One exception-table entry (code units; `end` exclusive).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ExcEntry {
    pub start: u32,
    pub end: u32,
    pub target: u32,
    pub depth: u32,
    pub lasti: bool,
}

fn put_varint6(out: &mut Vec<u8>, mut v: u32, first_mark: bool) {
    // big-endian 6-bit groups, 0x40 = "more follows", 0x80 marks an entry's first byte
    let mut groups = [0u8; 6];
    let mut k = 0;
    loop {
        groups[k] = (v & 63) as u8;
        k += 1;
        v >>= 6;
        if v == 0 {
            break;
        }
    }
    for j in (0..k).rev() {
        let mut b = groups[j];
        if j > 0 {
            b |= 0x40;
        }
        if first_mark && j == k - 1 {
            b |= 0x80;
        }
        out.push(b);
    }
}

pub fn encode_exception_table(entries: &[ExcEntry]) -> Vec<u8> {
    let mut out = Vec::new();
    for e in entries {
        put_varint6(&mut out, e.start, true);
        put_varint6(&mut out, e.end - e.start, false);
        put_varint6(&mut out, e.target, false);
        put_varint6(&mut out, (e.depth << 1) | e.lasti as u32, false);
    }
    out
}

pub fn decode_exception_table(t: &[u8]) -> Vec<ExcEntry> {
    let mut out = Vec::new();
    let mut p = 0usize;
    let read = |p: &mut usize| -> Option<u32> {
        let mut b = *t.get(*p)?;
        *p += 1;
        let mut v = (b & 63) as u32;
        while b & 64 != 0 {
            b = *t.get(*p)?;
            *p += 1;
            v = (v << 6) | (b & 63) as u32;
        }
        Some(v)
    };
    while p < t.len() {
        let (Some(start), Some(len), Some(target), Some(dl)) = (read(&mut p), read(&mut p), read(&mut p), read(&mut p)) else {
            break;
        };
        out.push(ExcEntry { start, end: start + len, target, depth: dl >> 1, lasti: dl & 1 != 0 });
    }
    out
}

// ---------------------------------------------------------------------------- location table

/// Source position of one code unit; `None` fields are unknown.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct Position {
    pub lineno: Option<u32>,
    pub end_lineno: Option<u32>,
    pub col: Option<u32>,
    pub end_col: Option<u32>,
}

impl Position {
    pub const NONE: Position = Position { lineno: None, end_lineno: None, col: None, end_col: None };
}

fn put_varint(out: &mut Vec<u8>, mut v: u32) {
    while v >= 64 {
        out.push(0x40 | (v & 63) as u8);
        v >>= 6;
    }
    out.push(v as u8);
}

fn put_svarint(out: &mut Vec<u8>, v: i64) {
    let u = if v < 0 { ((-v as u64) << 1) | 1 } else { (v as u64) << 1 };
    put_varint(out, u as u32);
}

/// Location-table entry kinds.
const LT_NO_COLUMNS: u8 = 13;
const LT_LONG: u8 = 14;
const LT_NONE: u8 = 15;

/// Encode positions for runs of code units: `runs` = (length in code units, position).
/// Runs longer than 8 units are split.
pub fn encode_linetable(runs: &[(u32, Position)], firstlineno: u32) -> Vec<u8> {
    let mut out = Vec::new();
    let mut prev_line = firstlineno as i64;
    for &(len, pos) in runs {
        let mut left = len;
        while left > 0 {
            let n = left.min(8);
            left -= n;
            let head = |code: u8| 0x80 | (code << 3) | (n as u8 - 1);
            let Some(line) = pos.lineno else {
                out.push(head(LT_NONE));
                continue;
            };
            let line = line as i64;
            let delta = line - prev_line;
            prev_line = line;
            let end_line = pos.end_lineno.map(|e| e as i64).unwrap_or(line);
            match (pos.col, pos.end_col) {
                (Some(c), Some(ec)) if end_line == line => {
                    if delta == 0 && c < 80 && ec >= c && ec - c < 16 {
                        out.push(head((c / 8) as u8));
                        out.push((((c % 8) << 4) | (ec - c)) as u8);
                    } else if (0..3).contains(&delta) && c < 128 && ec < 128 {
                        out.push(head(10 + delta as u8));
                        out.push(c as u8);
                        out.push(ec as u8);
                    } else {
                        out.push(head(LT_LONG));
                        put_svarint(&mut out, delta);
                        put_varint(&mut out, 0);
                        put_varint(&mut out, c + 1);
                        put_varint(&mut out, ec + 1);
                    }
                }
                (None, None) if end_line == line => {
                    out.push(head(LT_NO_COLUMNS));
                    put_svarint(&mut out, delta);
                }
                (c, ec) => {
                    out.push(head(LT_LONG));
                    put_svarint(&mut out, delta);
                    put_varint(&mut out, (end_line - line).max(0) as u32);
                    put_varint(&mut out, c.map(|c| c + 1).unwrap_or(0));
                    put_varint(&mut out, ec.map(|c| c + 1).unwrap_or(0));
                }
            }
        }
    }
    out
}

/// Decode a location table into one position per code unit (`ncodeunits` entries; units not
/// covered by the table get no position).
pub fn decode_linetable(t: &[u8], firstlineno: u32, ncodeunits: usize) -> Vec<Position> {
    let mut out = Vec::with_capacity(ncodeunits);
    let mut p = 0usize;
    let mut line = firstlineno as i64;
    let byte = |p: &mut usize| -> Option<u8> {
        let b = *t.get(*p)?;
        *p += 1;
        Some(b)
    };
    let varint = |p: &mut usize| -> Option<u32> {
        let mut shift = 0;
        let mut v: u32 = 0;
        loop {
            let b = byte(p)?;
            v |= ((b & 63) as u32).checked_shl(shift).unwrap_or(0);
            shift += 6;
            if b & 64 == 0 {
                break;
            }
        }
        Some(v)
    };
    let svarint = |p: &mut usize| -> Option<i64> {
        let u = varint(p)?;
        Some(if u & 1 != 0 { -((u >> 1) as i64) } else { (u >> 1) as i64 })
    };
    while p < t.len() && out.len() < ncodeunits {
        let Some(h) = byte(&mut p) else { break };
        let code = (h >> 3) & 15;
        let n = (h & 7) as usize + 1;
        let pos = match code {
            LT_NONE => Position::NONE,
            LT_NO_COLUMNS => {
                line += svarint(&mut p).unwrap_or(0);
                Position { lineno: Some(line as u32), end_lineno: Some(line as u32), col: None, end_col: None }
            }
            LT_LONG => {
                line += svarint(&mut p).unwrap_or(0);
                let el = varint(&mut p).unwrap_or(0) as i64;
                let c = varint(&mut p).unwrap_or(0);
                let ec = varint(&mut p).unwrap_or(0);
                Position {
                    lineno: Some(line as u32),
                    end_lineno: Some((line + el) as u32),
                    col: if c == 0 { None } else { Some(c - 1) },
                    end_col: if ec == 0 { None } else { Some(ec - 1) },
                }
            }
            10..=12 => {
                line += (code - 10) as i64;
                let c = byte(&mut p).unwrap_or(0) as u32;
                let ec = byte(&mut p).unwrap_or(0) as u32;
                Position { lineno: Some(line as u32), end_lineno: Some(line as u32), col: Some(c), end_col: Some(ec) }
            }
            _ => {
                let b = byte(&mut p).unwrap_or(0) as u32;
                let c = code as u32 * 8 + (b >> 4);
                Position { lineno: Some(line as u32), end_lineno: Some(line as u32), col: Some(c), end_col: Some(c + (b & 15)) }
            }
        };
        for _ in 0..n {
            if out.len() < ncodeunits {
                out.push(pos);
            }
        }
    }
    while out.len() < ncodeunits {
        out.push(Position::NONE);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exception_table_roundtrip() {
        let e = vec![
            ExcEntry { start: 2, end: 10, target: 40, depth: 0, lasti: false },
            ExcEntry { start: 100, end: 5000, target: 70000, depth: 3, lasti: true },
        ];
        assert_eq!(decode_exception_table(&encode_exception_table(&e)), e);
    }

    #[test]
    fn linetable_roundtrip() {
        let p = |l: u32, el: u32, c: Option<u32>, ec: Option<u32>| Position { lineno: Some(l), end_lineno: Some(el), col: c, end_col: ec };
        let runs = vec![
            (2, p(1, 1, Some(0), Some(5))),
            (10, p(2, 2, Some(4), Some(130))),
            (1, Position::NONE),
            (3, p(1000, 1003, Some(1), Some(2))),
            (1, p(999, 999, None, None)),
            (2, p(1001, 1001, Some(100), Some(120))),
        ];
        let t = encode_linetable(&runs, 1);
        let total: u32 = runs.iter().map(|r| r.0).sum();
        let d = decode_linetable(&t, 1, total as usize);
        let mut k = 0;
        for (n, pos) in &runs {
            for _ in 0..*n {
                assert_eq!(d[k], *pos, "unit {}", k);
                k += 1;
            }
        }
    }

    #[test]
    fn metadata() {
        assert_eq!(opname(LOAD_FAST), Some("LOAD_FAST"));
        assert_eq!(cache_entries(LOAD_GLOBAL), 4);
        assert_eq!(cache_entries(CALL), 3);
        assert_eq!(deopt(LOAD_ATTR_SLOT), LOAD_ATTR);
        assert_eq!(deopt(CALL_KW_PY), CALL_KW);
        assert_eq!(deopt(CALL_EX_PY), CALL_FUNCTION_EX);
        assert_eq!(deopt(RESUME_CHECK), RESUME);
        assert_eq!(deopt(JUMP_BACKWARD_JIT), JUMP_BACKWARD);
        assert_eq!(deopt(GET_ITER_SELF), GET_ITER);
        assert_eq!(deopt(LOAD_SUPER_ATTR_METHOD), LOAD_SUPER_ATTR);
        assert_eq!(compare_oparg(2, false), 72);
        assert_eq!(compare_oparg(0, true), 18);
        assert_eq!(compare_oparg(4, true), 148);
        assert!(has_arg(LOAD_FAST) && !has_arg(POP_TOP) && has_arg(JUMP) && !has_arg(POP_BLOCK));
    }
}
